SOURCES = {'turn_iteration_prep.py': '@dataclass\nclass IterationStart:\n    """``action``: ``"fallthrough"`` (run the iteration) or ``"break"`` (turn ends: interrupt,\n    review input budget or iteration budget exhausted — ``_turn_exit_reason`` set)."""\n\n    action: str\n    original_user_message: Any\n    api_call_count: Any\n    interrupted: Any\n    _turn_exit_reason: Any\n\ndef begin_iteration(\n    agent: Any, *, messages: Any, conversation_history: Any, original_user_message: Any,\n    api_call_count: Any, interrupted: Any, _turn_exit_reason: Any,\n) -> IterationStart:\n    """Iteration entry in the original order: apply a pending redirect, reset the checkpoint\n    dedup, then the interrupt / review-budget / iteration-budget exits. ``api_call_count`` is\n    incremented here (the grace call consumes its flag instead of the budget)."""\n    from agent.conversation_loop import (\n        _apply_active_turn_redirect, _review_input_budget_exhausted\n    )\n\n    def _verdict(action: str) -> IterationStart:\n        return IterationStart(\n            action=action, original_user_message=original_user_message,\n            api_call_count=api_call_count, interrupted=interrupted,\n            _turn_exit_reason=_turn_exit_reason,\n        )\n\n    _redirect_text = agent._drain_pending_redirect()\n    if _redirect_text:\n        _apply_active_turn_redirect(agent, messages, _redirect_text)\n        if isinstance(original_user_message, str):\n            original_user_message = (\n                f"{original_user_message}\\n\\n" f"User correction during the turn: {_redirect_text}"\n            )\n        agent._persist_session(messages, conversation_history)\n\n    # Reset per-turn checkpoint dedup so each iteration can take one snapshot.\n    agent._checkpoint_mgr.new_turn()\n\n    if agent._interrupt_requested:\n        interrupted = True\n        _issuer = interrupt_issuer(agent)\n        _turn_exit_reason = f"interrupted_by_system({_issuer})" if _issuer else "interrupted_by_user"\n        if not agent.quiet_mode:\n            agent._safe_print("\\n⚡ Breaking out of tool loop due to interrupt...")\n        return _verdict("break")\n\n    # Aggregate input budget for detached auxiliary forks bounds the whole review, not\n    # each request; checked between iterations so the crossing request\'s writes landed.\n    if _review_input_budget_exhausted(agent):\n        _turn_exit_reason = "review_input_budget_exhausted"\n        if not agent.quiet_mode:\n            agent._safe_print(\n                f"\\n⏹️  Review input budget exhausted "\n                f"({int(agent.session_input_tokens):,} tokens) — stopping "\n                f"the review tool loop before the next provider call.", diagnostic=True,\n            )\n        return _verdict("break")\n\n    api_call_count += 1\n    agent._api_call_count = api_call_count\n    agent._touch_activity(f"starting API call #{api_call_count}")\n\n    # Grace call: budget exhausted but the model gets one more call. Consume the\n    # flag so the loop exits after this iteration regardless of outcome.\n    if agent._budget_grace_call:\n        # Exhaustion retains one toolless grace call regardless of whether an opt-in\n        # checkpoint was emitted; the warning never extends the hard budget.\n        agent._budget_grace_call = False\n    elif not agent.iteration_budget.consume():\n        _turn_exit_reason = "budget_exhausted"\n        if not agent.quiet_mode:\n            agent._safe_print(f"\\n⚠️  Iteration budget exhausted ({agent.iteration_budget.used}/{agent.iteration_budget.max_total} iterations used)", diagnostic=True)\n        return _verdict("break")\n    return _verdict("fallthrough")\n\n@dataclass\nclass RetryRestartVerdict:\n    """``action``: ``"fallthrough"`` (a response is ready — process it), ``"continue"``\n    (a restart flag re-issues the iteration: redirect / compressed / rebuilt-for-fallback /\n    length continuation) or ``"break"`` (turn ends: interrupted, non-actionable compaction\n    handoff, or every retry exhausted without a response)."""\n\n    action: str\n    current_turn_user_idx: Any\n    final_response: Any\n    retry_count: Any\n    restart_count: Any\n    api_call_count: Any\n    _preflight_compression_blocked: Any\n    _turn_exit_reason: Any\n\ndef apply_retry_restarts(\n    agent: Any, *, _retry: Any, response: Any, interrupted: Any, messages: Any,\n    conversation_history: Any, user_message: Any, api_kwargs: Any, current_turn_user_idx: Any,\n    final_response: Any, retry_count: Any, max_retries: Any, api_call_count: Any,\n    restart_count: Any, length_continue_retries: Any,\n    _preflight_compression_blocked: Any, _turn_exit_reason: Any,\n) -> RetryRestartVerdict:\n    """Consume the ``TurnRetryState`` restart flags after the retry loop, in the original\n    priority order. Refunds the iteration budget/count for restarts that produced no valid\n    assistant item; ``restart_with_rebuilt_messages`` is the single consumer that clears\n    ``_preflight_compression_blocked`` so the fallback gets a fresh preflight (#84733).\n\n    The two refunding restart paths (redirect and rebuilt-for-fallback) are bounded by\n    ``max_retries`` via ``restart_count`` (restarts since the last response) so a runaway\n    interrupt/redirect that keeps re-arming a restart flag cannot refund the budget\n    forever and hold the turn lease indefinitely."""\n\n    from agent.conversation_loop import (\n        _HANDOFF_SKIP_FINAL_RESPONSE, _should_skip_model_call_for_reference_handoff\n    )\n\n    def _verdict(action: str) -> RetryRestartVerdict:\n        return RetryRestartVerdict(\n            action=action, current_turn_user_idx=current_turn_user_idx,\n            final_response=final_response, retry_count=retry_count, restart_count=restart_count,\n            api_call_count=api_call_count,\n            _preflight_compression_blocked=_preflight_compression_blocked,\n            _turn_exit_reason=_turn_exit_reason,\n        )\n\n    if _retry.restart_with_redirected_messages:\n        restart_count += 1\n        if restart_count > max_retries:\n            # A redirect/interrupt keeps re-arming this flag: stop refunding the iteration\n            # budget and re-issuing the same logical iteration, or a runaway turn holds the\n            # turn lease indefinitely (redirect restarts previously had no bound).\n            _turn_exit_reason = "redirect_restart_limit_exceeded"\n            logger.warning(\n                "Redirected-message restart limit (%s) exceeded; ending turn instead of "\n                "refunding the iteration budget indefinitely.",\n                max_retries,\n            )\n            # The correction that tripped the cap was never applied; hand it back as the\n            # next user turn (result["pending_steer"]) instead of losing it to clear_interrupt().\n            _unapplied = agent._drain_pending_redirect()\n            if _unapplied:\n                agent.steer(_unapplied)\n            return _verdict("break")\n        # Cancelled request produced no valid assistant item: reuse the same logical\n        # iteration after the outer loop appends partial context + correction.\n        api_call_count -= 1\n        agent.iteration_budget.refund()\n        _retry.restart_with_redirected_messages = False\n        return _verdict("continue")\n\n    if interrupted:\n        _turn_exit_reason = interrupted_during_api_call_reason(agent)\n        return _verdict("break")\n\n    if _retry.restart_with_compressed_messages:\n        api_call_count -= 1\n        agent.iteration_budget.refund()\n        # Compression restarts count toward the retry limit so a compression that\n        # shrinks messages but not enough can\'t loop forever.\n        retry_count += 1\n        _retry.restart_with_compressed_messages = False\n        if _should_skip_model_call_for_reference_handoff(\n            # Compression rebuilt the list (tail messages are fresh compaction copies), so the\n            # pre-compression index of this turn\'s user message is stale. Re-anchor both index trackers: the\n            # api_content stamp below, the loop\'s injection site, and the flush\'s persist-override row\n            # (#48677) must all target the surviving dict, not a stale position. Exact-content match first\n            # so a todo-snapshot user message appended after the tail can\'t steal the anchor.\n            messages, user_message\n        ):\n            logger.info(\n                "Skipping compressed-restart model call: reference-only "\n                "handoff would be the sole active user turn (#80622)"\n            )\n            if not final_response:\n                final_response = _HANDOFF_SKIP_FINAL_RESPONSE\n            _turn_exit_reason = "compaction_handoff_not_actionable"\n            return _verdict("break")\n        # In-loop compression rebuilt `messages`; re-anchor the current-turn index\n        # like the prologue, AFTER the handoff guard (it may re-append this turn\'s\n        # ask). A stale anchor injects prefetch into a historical row.\n        current_turn_user_idx = _reanchor(agent, messages, user_message)\n        return _verdict("continue")\n\n    if _retry.restart_with_rebuilt_messages:\n        restart_count += 1\n        if restart_count > max_retries:\n            # A stall/failure keeps re-escalating to the fallback chain: stop refunding the\n            # iteration budget and re-issuing, or a runaway turn holds the turn lease\n            # indefinitely (rebuilt restarts previously had no bound).\n            _turn_exit_reason = "rebuilt_restart_limit_exceeded"\n            logger.warning(\n                "Rebuilt-message restart limit (%s) exceeded; ending turn instead of "\n                "refunding the iteration budget indefinitely.",\n                max_retries,\n            )\n            return _verdict("break")\n        # A stall/failure escalated to the fallback chain: re-issue against the\n        # active fallback provider, refunding budget/count for the stalled attempt.\n        api_call_count -= 1\n        agent.iteration_budget.refund()\n        _retry.restart_with_rebuilt_messages = False\n        # Failover shrank the compressor window: clear the preflight block so\n        # preflight re-runs before the first fallback call (single consumer).\n        _preflight_compression_blocked = False\n        return _verdict("continue")\n\n    if _retry.restart_with_length_continuation:\n        # Boost the output budget per retry (shared ladder, see boosted_output_cap).\n        agent._ephemeral_max_output_tokens = boosted_output_cap(\n            agent, agent._requested_output_cap_from_api_kwargs(api_kwargs), length_continue_retries\n        )\n        return _verdict("continue")\n\n    # All retries may exhaust with `response` still None; break out cleanly.\n    if response is None:\n        _turn_exit_reason = "all_retries_exhausted_no_response"\n        agent._emit_diagnostic_status("❌ The model provider didn\'t answer after all retries. Send /retry, or switch models with /model.")\n        agent._persist_session(messages, conversation_history)\n        return _verdict("break")\n    # A response arrived, so the turn is not stuck re-issuing a cancelled request: start\n    # the refunding-restart bound over (restart_count = restarts since the last response).\n    # Counting every mid-turn correction for the whole turn ended healthy interactive\n    # turns on the (max_retries + 1)th message (#128000).\n    restart_count = 0\n    return _verdict("fallthrough")\n', 'turn_api_call.py': '@dataclass\nclass ApiCallVerdict:\n    """``action``: ``"fallthrough"`` (``response`` is ready for verification) or ``"break"``\n    (a redirect crossed the response — rebuild armed on ``_retry`` or ``interrupted``)."""\n\n    action: str\n    response: Any\n    thinking_spinner: Any\n    interrupted: Any\n\ndef perform_api_call(\n    agent: Any, *, api_kwargs: Any, _original_api_kwargs: Any, _llm_middleware_trace: Any,\n    _moa_prepared_request: Any, _retry: Any, thinking_spinner: Any, retry_count: Any,\n    api_call_count: Any, api_request_id: Any, effective_task_id: Any, turn_id: Any,\n    interrupted: Any,\n) -> ApiCallVerdict:\n    """Issue the request (see ``_should_stream`` for the streaming decision)."""\n    response = None\n\n    def _verdict(action: str) -> ApiCallVerdict:\n        return ApiCallVerdict(\n            action=action, response=response, thinking_spinner=thinking_spinner,\n            interrupted=interrupted,\n        )\n\n    def _stop_spinner():\n        nonlocal thinking_spinner\n        thinking_spinner = stop_thinking_spinner(agent, thinking_spinner)\n\n    _use_streaming = _should_stream(agent)\n\n    def _perform_api_call(next_api_kwargs):\n        if agent.api_mode == "codex_responses":\n            next_api_kwargs = agent._get_transport().preflight_kwargs(\n                next_api_kwargs, allow_stream=False, is_github_responses=agent._is_copilot_url(),\n                sanitize_harmony_tokens=agent._is_codex_backend(),\n            )\n        if _use_streaming:\n            return agent._interruptible_streaming_api_call(\n                next_api_kwargs, on_first_delta=_stop_spinner\n            )\n        from agent import relay_llm\n\n        return relay_llm.execute(\n            next_api_kwargs,\n            agent._interruptible_api_call,\n            session_id=str(agent.session_id or ""),\n            name=str(agent.provider or "provider"),\n            model_name=str(agent.model or ""),\n            metadata={\n                "api_mode": agent.api_mode,\n                "api_request_id": api_request_id,\n                "call_role": (\n                    "delegated"\n                    if getattr(agent, "is_subagent", False)\n                    else "fallback"\n                    if int(getattr(agent, "_fallback_index", 0) or 0) > 0\n                    else "primary"\n                ),\n                "retry_count": retry_count,\n            },\n            defer_logical_completion=True,\n        )\n\n    from hermes_cli.middleware import run_llm_execution_middleware\n\n    # The ``_model_request_active`` bracket is taken under the redirect lock when one exists,\n    # so redirect() can\'t observe a half-toggled flag.\n    _model_request_active = getattr(agent, "_model_request_active", None)\n    _redirect_lock = getattr(agent, "_pending_redirect_lock", None)\n    _bracket = nullcontext() if _redirect_lock is None else _redirect_lock\n    with _bracket:\n        if _model_request_active is not None:\n            _model_request_active.set()\n    try:\n        response = run_llm_execution_middleware(\n            api_kwargs, _perform_api_call, original_request=_original_api_kwargs,\n            task_id=effective_task_id, turn_id=turn_id, api_request_id=api_request_id,\n            session_id=agent.session_id or "", platform=agent.platform or "", model=agent.model,\n            provider=agent.provider, base_url=agent.base_url, api_mode=agent.api_mode,\n            api_call_count=api_call_count, middleware_trace=list(_llm_middleware_trace),\n        )\n    finally:\n        with _bracket:\n            if _model_request_active is not None:\n                _model_request_active.clear()\n            _redirect_crossed_response = (\n                bool(agent._pending_redirect) if _redirect_lock is not None\n                else agent._has_pending_redirect()\n            )\n    if _redirect_crossed_response:\n        # Response and redirect can cross threads: discard the now-stale\n        # response and rebuild from the correction rather than lose it.\n        thinking_spinner = stop_thinking_spinner(agent, thinking_spinner)\n        if agent.clear_interrupt(preserve_redirect=True):\n            _retry.restart_with_redirected_messages = True\n        else:\n            interrupted = True\n        return _verdict("break")\n    return _verdict("fallthrough")\n', 'conversation_loop.py': '_INTERRUPT_SCAFFOLD_MARKER = \'[This response was interrupted by a user correction.]\'\n\ndef _review_input_budget_exhausted(agent: Any) -> bool:\n    """True when a detached review fork has replayed its aggregate input budget.\n\n    Only forks with an explicit ``_review_input_token_budget`` are gated (#93057). Fires\n    at the top of the NEXT iteration, so the budget-crossing request completes first."""\n    budget = getattr(agent, "_review_input_token_budget", None)\n    if not isinstance(budget, int) or isinstance(budget, bool) or budget <= 0:\n        return False\n    used = getattr(agent, "session_input_tokens", 0)\n    return isinstance(used, int) and not isinstance(used, bool) and used >= budget\n\ndef _apply_active_turn_redirect(agent: Any, messages: list[dict[str, Any]], text: str) -> None:\n    """Append a provider-safe checkpoint and correction to the live turn so role alternation\n    holds and cached messages stay byte-identical. INVARIANTS: raw chain-of-thought never enters\n    replayable content (inlined CoT reads as a prefill jailbreak and bricks the session with\n    empty-response storms); the interruption scaffold is replay text carried only in the user\n    correction\'s ``api_content``; an on-screen-empty placeholder is ``display_kind=hidden``."""\n    visible = agent._strip_think_blocks(getattr(agent, "_current_streamed_assistant_text", "") or "").strip()\n\n    checkpoint_parts = [_INTERRUPT_SCAFFOLD_MARKER]\n    if is_runaway_repetition(visible):\n        # Runaway shape only (a correct batch-style partial stays replayable): the looped bytes must\n        # reach neither the replayed correction nor the placeholder below (empty ``visible`` takes\n        # the hidden shape).\n        checkpoint_parts.append(REPETITION_LOOP_INTERRUPTED)\n        visible = ""\n    elif visible:\n        checkpoint_parts += ["Visible response before the interruption:", visible]\n    checkpoint = "\\n\\n".join(checkpoint_parts)\n    correction = f"[Context from the interrupted assistant response]\\n{checkpoint}\\n\\n{text}"\n\n    # The live tail is normally user or tool, so an assistant placeholder + correction\n    # keeps strict alternation; if the tail is already assistant, the checkpoint is folded\n    # into the user correction instead of creating assistant→assistant. The placeholder\n    # preserves alternation only — scaffold bytes must never land in it, since api_content\n    # is substituted back into content on replay (#81841).\n    if not (messages and messages[-1].get("role") == "assistant"):\n        # Hidden row with a neutral api_content (#88955). Never _INTERRUPT_SCAFFOLD_MARKER:\n        # as assistant text the model echoes it (#81841).\n        append_message(messages, {"role": "assistant", "content": visible} if visible else hidden_interrupt_placeholder_row())\n    # Transcript shows the user\'s own words; the provider replays the scaffolded form.\n    append_message(messages, {"role": "user", "content": text, "api_content": correction})\n\n    # Stateful scrubber for <memory-context> spans split across stream deltas (#5719).  sanitize_context()\n    # alone can\'t survive chunk boundaries because the block regex needs both tags in one string.\n    # Stateful scrubber for reasoning/thinking tags in streamed deltas (#17924). Replaces the per-delta\n    # _strip_think_blocks regex that destroyed downstream state (e.g. MiniMax-M2.7 streaming \'<think>\' as\n    # delta1 and \'Let me check\' as delta2 — the regex erased delta1, so downstream state machines never\n    # learned a block was open and leaked delta2 as content).\n    agent._current_streamed_assistant_text = ""\n    agent._stream_needs_break = True\n', 'message_metadata.py': 'def stamp_message_timestamp(\n    message: _Message,\n    *,\n    timestamp: Optional[float] = None,\n) -> _Message:\n    """Attach a creation timestamp without replacing source-provided time.\n\n    Gateway adapters can supply the platform event time; all other callers use\n    the local wall clock. Returns the same mapping for use at append sites.\n    """\n    if message.get("timestamp") is None:\n        message["timestamp"] = wall_time() if timestamp is None else timestamp\n    return message\n\ndef append_message(\n    messages: list[Any],\n    message: _Message,\n    *,\n    timestamp: Optional[float] = None,\n) -> _Message:\n    """Stamp and append one live transcript message."""\n    messages.append(stamp_message_timestamp(message, timestamp=timestamp))\n    return message\n', 'run_agent.py': 'def _content_has_real_payload(content: Any) -> bool:\n        """True when assistant ``content`` carries anything beyond (redacted) thinking blocks / whitespace."""\n        if isinstance(content, str):\n            return bool(content.strip())\n        if isinstance(content, list):\n            for block in content:\n                if not isinstance(block, dict):\n                    if block:  # non-empty non-dict string etc.\n                        return True\n                    continue\n                btype = block.get("type")\n                if btype == "text":\n                    text = block.get("text", "")\n                    if isinstance(text, str) and text.strip():\n                        return True\n                elif btype not in {"thinking", "redacted_thinking"}:\n                    return True  # tool_use, image, document, etc. — real payload\n            return False\n        return content is not None and content != ""\n', 'repetition_guard.py': '"""Cheap content-sanity checks for model output, completed or still streaming.\n\nA model in a degenerate repetition loop can spend its ENTIRE output budget echoing one fragment;\nthe ``finish_reason=length`` continuation would then stitch it into the final response with a\n"continue" nudge (one incident: a 60k-char turn delivered as 31 Discord messages). This detects\nrepetition-dominated fragments BEFORE the nudge so the turn aborts with a clear error. Deliberately\nconservative: only LONG verbatim repeats (60+ chars) covering a majority of the fragment trip it.\n"""\n\nfrom __future__ import annotations\n\nimport math\nfrom collections import Counter\n\n# Below this length the check doesn\'t run: short truncations trivially\n# contain repeated tokens and are legitimately continued.\nMIN_FRAGMENT_LENGTH = 400\n# Exact-repeat window; far beyond ordinary phrasing reuse (citations, headings, similar code).\n_REPEAT_WINDOW = 60\n# A window repeating at least this often is a signal even for short fragments.\n_MIN_REPEAT_COUNT = 5\n# "Repetition-dominated" = repeated windows cover at least this fraction.\n_DOMINANCE_RATIO = 0.5\n\n# What an interrupt checkpoint says INSTEAD of a repetition-dominated partial. Replaying the\n# looped bytes (as the redirect\'s api_content or as the interrupted assistant row) re-seeds the\n# loop on the next request and the corruption survives restarts (#112764); the model only needs\n# to know the reply degenerated and was cut off.\nREPETITION_LOOP_INTERRUPTED = "[the reply degenerated into a repetition loop and was interrupted]"\n\n# Sampling bounds keep the general path linear in output size with a small,\n# fixed multiplier. A dominant contiguous run necessarily crosses many of\n# these evenly spaced anchors.\n_MAX_ANCHOR_SAMPLES = 32\n_MAX_ANCHOR_MATCHES = 8\n\n\n# ``is_runaway_repetition``: a multi-line partial must be mostly copies of a few lines. Batch-style\n# output (distinct INSERT rows, similar table rows) shares long prefixes and trips the window\n# scan, but every line is distinct; a loop re-emits the same line(s).\n_RUNAWAY_DISTINCT_LINE_RATIO = 0.5\n\n# The finish_reason="stop" path discards a COMPLETED answer, so it only aborts at runaway scale:\n# real stop-path loops (#100716) run 80k-350k chars, while asked-for repeats ("say X 50 times",\n# identical table rows, templated YAML) stay in the low KB and must be delivered.\nSTOP_PATH_MIN_CHARS = 16_000\n\n# A live stream is judged on at most this much of its latest text, so one check stays bounded\n# however long the reply grows.\n_STREAM_TAIL_CHARS = 4 * STOP_PATH_MIN_CHARS\n\n\ndef is_repetition_dominated(text: str) -> bool:\n    """True when a contiguous run of at least five exact repetitions covers at least half\n    of ``text`` — the signature of a model repetition loop (issue #86581). Coverage is measured\n    with the true period, so long multi-line loop units count fully. Fail-open for short input.\n    """\n    if not isinstance(text, str):\n        return False\n    n = len(text)\n    if n < MIN_FRAGMENT_LENGTH:\n        return False\n\n    # Fast path: one normalized line duplicated enough to cover half the fragment (the common echo shape).\n    if _line_repetition_dominated(text, n):\n        return True\n\n    # Window-count scan (#86581) catches loops whose repeats differ by a counter or noise token;\n    # the periodic scan catches long exact units whose 60-char windows each recur too rarely.\n    return _window_count_dominated(text, n) or _periodic_run_dominated(text, n)\n\n\ndef _window_count_dominated(text: str, n: int) -> bool:\n    """True when one 60-char window recurs often enough to cover half of ``text``."""\n    window = _REPEAT_WINDOW\n    needed = max(_MIN_REPEAT_COUNT, math.ceil(n * _DOMINANCE_RATIO / window))\n    counts: dict[str, int] = {}\n    for i in range(n - window + 1):\n        key = text[i : i + window]\n        c = counts.get(key, 0) + 1\n        if c >= needed:\n            return True\n        counts[key] = c\n    return False\n\n\ndef _periodic_run_dominated(text: str, n: int) -> bool:\n    """Detect a dominant exact periodic run from evenly spaced anchors.\n\n    Matching a 60-character anchor at a later position supplies a candidate\n    period. Expanding the equality ``text[i] == text[i + period]`` in both\n    directions recovers the full run, so coverage is measured using the true\n    repeating unit rather than crediting every occurrence with only 60 chars.\n    """\n    window = _REPEAT_WINDOW\n    max_start = n - window\n    if max_start < 1:\n        return False\n\n    sample_step = max(\n        1,\n        (max_start + _MAX_ANCHOR_SAMPLES - 2) // (_MAX_ANCHOR_SAMPLES - 1),\n    )\n    sample_starts = list(range(0, max_start + 1, sample_step))\n    if sample_starts[-1] != max_start:\n        sample_starts.append(max_start)\n\n    # Runs already expanded and rejected, as (left, right, period). A later anchor inside one of\n    # them whose period is a multiple of that run\'s period would re-walk the same run.\n    rejected: list[tuple[int, int, int]] = []\n    for start in sample_starts:\n        anchor = text[start : start + window]\n        search_from = start + 1\n        for _ in range(_MAX_ANCHOR_MATCHES):\n            match = text.find(anchor, search_from)\n            if match < 0:\n                break\n            period = match - start\n            search_from = match + 1\n            if any(lo <= start < hi and period % p == 0 for lo, hi, p in rejected):\n                continue\n            left, right = _expand_run(text, n, start, period, window)\n            if right - left >= _MIN_REPEAT_COUNT * period and right - left >= n * _DOMINANCE_RATIO:\n                return True\n            rejected.append((left, right, period))\n    return False\n\n\ndef _expand_run(text: str, n: int, start: int, period: int, matched: int) -> tuple[int, int]:\n    """Expand one known equal window to the ``[left, right)`` bounds of its exact periodic run."""\n    left = start\n    while left > 0 and text[left - 1] == text[left - 1 + period]:\n        left -= 1\n\n    right = start + matched\n    while right + period < n and text[right] == text[right + period]:\n        right += 1\n    return left, right + period\n\n\ndef is_runaway_repetition(text: str) -> bool:\n    """Stricter than :func:`is_repetition_dominated`: also require the runaway shape.\n\n    An interrupt checkpoint DROPS the partial when this fires, so a legitimately repetitive but\n    correct reply (distinct batch rows) must not qualify: repeated windows have to dominate AND,\n    when the text has line structure, at most half of its non-empty lines may be distinct.\n    """\n    if not is_repetition_dominated(text):\n        return False\n    lines = [line.strip() for line in text.splitlines()]\n    lines = [line for line in lines if line]\n    if len(lines) < _MIN_REPEAT_COUNT:\n        return True  # no line structure to judge by: a dominated single-line loop\n    return len(set(lines)) <= len(lines) * _RUNAWAY_DISTINCT_LINE_RATIO\n\n\ndef _line_repetition_dominated(text: str, n: int) -> bool:\n    """True when a single normalized line covers half the fragment via repeats."""\n    counts = Counter(norm for norm in (line.strip() for line in text.splitlines()) if norm)\n    return any(c >= _MIN_REPEAT_COUNT and c * len(line) >= n * _DOMINANCE_RATIO for line, c in counts.items())\n\n\nclass RunawayStreamWatch:\n    """The stop-path criterion applied WHILE one channel (visible text or reasoning) streams.\n\n    A stream that keeps producing never reaches a completion check, and endpoints without an\n    output cap (#127234) keep a looping model going for as long as the turn lives. The first\n    check runs at ``STOP_PATH_MIN_CHARS`` (asked-for repeats stay below it, as on the stop path)\n    and the gap doubles until it reaches one tail window, then stays there. A fixed stride keeps a\n    loop that starts late in a long reply from streaming as long as the reply already was before\n    a check sees it; each check reads only the tail, so the total work stays linear in the output.\n    Each check also trims the held text to the tail, and checks are at most one tail window apart,\n    so the watch never holds more than two tail windows plus the latest delta.\n    """\n\n    __slots__ = ("_chars", "_next_check", "_parts")\n\n    def __init__(self) -> None:\n        self._parts: list[str] = []\n        self._chars = 0\n        self._next_check = STOP_PATH_MIN_CHARS\n\n    def feed(self, text: str) -> bool:\n        """Add one delta; True once the channel has become a runaway loop."""\n        if not text:\n            return False\n        self._parts.append(text)\n        self._chars += len(text)\n        if self._chars < self._next_check:\n            return False\n        self._next_check = self._chars + min(self._chars, _STREAM_TAIL_CHARS)\n        tail = "".join(self._parts)[-_STREAM_TAIL_CHARS:]\n        self._parts = [tail]\n        return is_runaway_repetition(tail)\n', 'agent_runtime_helpers_placeholders.py': '"""Interrupt placeholder wording substituted into empty non-final wire rows.\n\nSplit out of ``agent/agent_runtime_helpers.py`` (code-health size ratchet); a leaf module with no\nimports so every reader (runtime helpers, turn prep, the conversation loop) can import it directly.\n"""\n\n# Placeholder for an empty non-final message the provider would reject. This is the single source of\n# the wording: every healing path imports it from here, so healed transcripts read consistently.\n#\n# Wording matters: this text is substituted into an assistant row\'s ``content`` on the wire copy\n# (``fill_empty_non_final_wire_payload``, ``repair_empty_non_final_messages``, and the projection in\n# ``run_conversation``), so the model reads it as something IT said. A short natural-language phrase\n# in that position gets echoed verbatim — a clean ``finish_reason=stop`` turn answering an ordinary\n# instruction with just the placeholder (#132949, and #81841 for the same hazard on the scaffold).\n# Keep it a structural label the model has no conversational reason to reproduce, never prose.\n_INTERRUPTED_PLACEHOLDER = "[interrupt: no assistant output for this turn]"\n\n# The spelling shipped before #132949. Models reproduce it verbatim, so rows already carrying it\n# stay poisoned after the wording change; the replay filters reference this name to retire them.\n_LEGACY_INTERRUPTED_PLACEHOLDER = "[response interrupted]"\n\n\ndef hidden_interrupt_placeholder_row() -> dict:\n    """A fresh assistant row that is invisible in transcripts but carries the placeholder as its\n    non-empty ``api_content``, so the pre-call sanitizer does not re-heal it every call (#88955)."""\n    return {"role": "assistant", "content": "", "display_kind": "hidden", "api_content": _INTERRUPTED_PLACEHOLDER}\n'}
